import logging
import sys

import boto3
from botocore.exceptions import ClientError

from app.config import settings


logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s %(levelname)s %(name)s — %(message)s",
)
log = logging.getLogger(__name__)


def _dynamo():
    return boto3.client(
        "dynamodb",
        **settings.aws_client_kwargs(settings.dynamodb_endpoint_url),
    )


def _sqs():
    return boto3.client(
        "sqs",
        **settings.aws_client_kwargs(settings.sqs_endpoint_url),
    )


def ensure_table(client, table_name: str, pk: str = "txn_id") -> None:
    try:
        client.create_table(
            TableName=table_name,
            AttributeDefinitions=[{"AttributeName": pk, "AttributeType": "S"}],
            KeySchema=[{"AttributeName": pk, "KeyType": "HASH"}],
            BillingMode="PAY_PER_REQUEST",
        )
        log.info("Table '%s' created", table_name)
    except ClientError as exc:
        if exc.response["Error"]["Code"] == "ResourceInUseException":
            log.info("Table '%s' already exists", table_name)
        else:
            raise


def ensure_queue(client, queue_name: str) -> str:
    try:
        response = client.create_queue(QueueName=queue_name)
        log.info("Queue '%s' created", queue_name)
        return response["QueueUrl"]
    except ClientError as exc:
        if exc.response["Error"]["Code"] in (
            "QueueAlreadyExists",
            "AWS.SimpleQueueService.QueueDeletedRecently",
        ):
            response = client.get_queue_url(QueueName=queue_name)
            log.info("Queue '%s' already exists", queue_name)
            return response["QueueUrl"]
        raise


def verify_aws_resources() -> None:
    dynamo = _dynamo()
    sqs = _sqs()

    table = dynamo.describe_table(
        TableName=settings.dynamodb_table_name
    )["Table"]
    key_schema = {
        item["AttributeName"]: item["KeyType"]
        for item in table["KeySchema"]
    }

    expected_key = "transaction_id"
    if key_schema.get(expected_key) != "HASH":
        raise RuntimeError(
            f"Table {settings.dynamodb_table_name} must have "
            f"{expected_key} as its HASH key; found {key_schema}"
        )

    sqs.get_queue_url(QueueName=settings.sqs_queue_name)
    log.info("Terraform-managed DynamoDB table and SQS queue are available")


def bootstrap_local_resources() -> None:
    dynamo = _dynamo()
    sqs = _sqs()

    ensure_table(dynamo, settings.dynamodb_table_name, pk="txn_id")
    ensure_table(dynamo, "ibts-idempotency-records", pk="idempotency_key")
    ensure_table(dynamo, "ibts-routing-table", pk="bank_code")
    ensure_queue(sqs, settings.sqs_queue_name)
    log.info("LocalStack resources are ready")


def main() -> None:
    if settings.aws_mode:
        log.info("Verifying AWS resources in region %s", settings.aws_default_region)
        verify_aws_resources()
    else:
        log.info(
            "Bootstrapping local resources at %s",
            settings.dynamodb_endpoint_url,
        )
        bootstrap_local_resources()


if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        log.critical("Resource setup failed: %s", exc)
        sys.exit(1)
